@import "tailwindcss";
@import "@fontsource-variable/geist";

@source "./**/*.{ts,tsx}";

:root {
  font-family: "Geist Variable", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: #f7f3ee;
  background: #090708;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --font-editorial: "Newsreader", "Playfair Display", Georgia, "Times New Roman", serif;
  --color-ember-primary: #ff6b2b;
  --color-ember-light: #ffa166;
  --color-ember-dim: #993d14;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: #090708;
  color: #f7f3ee;
  overflow-x: hidden;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

.font-editorial {
  font-family: var(--font-editorial);
}

.landing-page {
  position: relative;
  overflow: hidden;
  background: #090708;
  color: #f7f3ee;
}

.landing-page::before {
  position: fixed;
  z-index: 0;
  inset: 0;
  pointer-events: none;
  content: "";
  opacity: 0.035;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.75' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 180px 180px;
}

.landing-page > * {
  position: relative;
  z-index: 1;
}

/* Cinematic Ember Glow & Gradients */
.text-gradient-ember {
  background: linear-gradient(135deg, #ffffff 0%, #ffc499 35%, #ff7a2b 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.text-gradient-editorial {
  background: linear-gradient(180deg, #ffffff 10%, #edd8c7 90%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.bg-ember-glow {
  background: radial-gradient(circle at 50% 50%, rgba(255, 107, 43, 0.18) 0%, rgba(255, 107, 43, 0.03) 55%, transparent 75%);
}

.glass-panel {
  background: rgba(18, 14, 16, 0.65);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.glass-panel-hover:hover {
  background: rgba(24, 18, 20, 0.85);
  border-color: rgba(255, 120, 50, 0.25);
}

.portal-beam {
  box-shadow: 0 0 50px 10px rgba(255, 120, 50, 0.25), 0 0 100px 30px rgba(255, 80, 20, 0.12);
}

@keyframes pulseSubtle {
  0%, 100% {
    opacity: 0.85;
    transform: scale(1);
  }
  50% {
    opacity: 1;
    transform: scale(1.02);
  }
}

.animate-pulse-subtle {
  animation: pulseSubtle 6s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  *,
  ::before,
  ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

